//! Integration test: rer vs rez on rez's bundled benchmark dataset.
//!
//! Runs all 188 benchmark resolve requests (against ~1.3k package families /
//! ~18k versions) through the rez-faithful [`Solver`] and compares the outcome
//! against rez's own recorded results — the goal is a 1:1 match.
//!
//! # Fixtures
//!
//! The fixtures under `data_set/benchmark_*.json` are generated by
//! `scripts/prepare_benchmark_data.py` (from the `rez` git submodule) and are
//! **gitignored**. If they are absent this test prints how to generate them
//! and returns without failing, so a plain `cargo test` checkout stays green.
//!
//! # What is checked
//!
//! Every case must match rez exactly — this is a strict 1:1 gate:
//! * **Solve status** must match rez (`success` ↔ solved, `failed` ↔ failed).
//! * For solved cases, rer's resolved package set must equal rez's exactly,
//!   including the variant index (rez records each variant as
//!   `"name/version/package.py[idx]"` — `[]` means "no variant", `[N]` means
//!   variant N). A divergence on variant index — same package, same version,
//!   different variant — is a real semantic difference (the variant's own
//!   `requires` differ) and is treated as a test failure.
//! * A solver panic is always a hard failure.
//!
//! The test is `#[ignore]`d because the full release run takes minutes; it is
//! run explicitly by the `benchmark` CI workflow (`cargo test --release ...
//! -- --ignored`), and can be chunked locally with `BENCH_RANGE=start:end`.

use rer_resolver::rez_solver::{PackageRepo, Requirement, Solver, SolverStatus};
use rer_resolver::PackageData;
use serde::Deserialize;
use std::collections::HashMap;
use std::panic::{catch_unwind, AssertUnwindSafe};
use std::path::PathBuf;
use std::rc::Rc;

/// `package name → version → PackageData`, as produced by the prep script.
/// Distinct from the resolver crate's [`PackageRepo`] (which is now a struct
/// with optional loader support — issue #86); this is just the JSON shape.
type RepoMap = HashMap<String, HashMap<String, PackageData>>;

/// One trimmed entry from rez's recorded `resolves.json`.
#[derive(Deserialize)]
struct BenchmarkCase {
    request: Vec<String>,
    /// `"success"` or `"failed"`.
    status: String,
    /// rez's resolved packages (`"name/version/package.py[variant]"`); absent
    /// for failed resolves.
    resolved_packages: Option<Vec<String>>,
}

fn data_set_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../data_set")
}

/// The `[start, end)` slice of cases to run, from the `BENCH_RANGE=start:end`
/// environment variable (default: all cases). Lets the otherwise ~9-minute
/// release run be split across several invocations under a test timeout.
fn bench_range(total: usize) -> (usize, usize) {
    match std::env::var("BENCH_RANGE") {
        Ok(spec) => {
            let (s, e) = spec.split_once(':').expect("BENCH_RANGE must be start:end");
            (
                s.parse().expect("BENCH_RANGE start"),
                e.parse::<usize>().expect("BENCH_RANGE end").min(total),
            )
        }
        Err(_) => (0, total),
    }
}

/// Load and parse a fixture file, or `None` if it does not exist yet.
fn load_json<T: for<'de> Deserialize<'de>>(name: &str) -> Option<T> {
    let path = data_set_dir().join(name);
    let data = std::fs::read_to_string(&path).ok()?;
    Some(
        serde_json::from_str(&data)
            .unwrap_or_else(|e| panic!("failed to parse {}: {}", path.display(), e)),
    )
}

/// Normalize rez's resolved-package list (`"name/version/package.py[idx]"`)
/// to a sorted, deduped `(name, version, variant_index)` set.
///
/// `[]` (empty brackets) → `None`; `[N]` → `Some(N)`. Anything else is
/// skipped as malformed.
fn normalize_rez(entries: &[String]) -> Vec<(String, String, Option<usize>)> {
    let mut out: Vec<(String, String, Option<usize>)> = entries
        .iter()
        .filter_map(|entry| {
            let mut parts = entry.splitn(3, '/');
            let name = parts.next()?.to_string();
            let version = parts.next()?.to_string();
            let suffix = parts.next()?; // e.g. "package.py[1]" or "package.py[]"
            let open = suffix.find('[')?;
            let close = suffix.rfind(']')?;
            let inner = &suffix[open + 1..close];
            let variant_index = if inner.is_empty() {
                None
            } else {
                Some(inner.parse::<usize>().ok()?)
            };
            Some((name, version, variant_index))
        })
        .collect();
    out.sort();
    out.dedup();
    out
}

/// Run one resolve through the rez-faithful solver.
///
/// Returns `Some(set)` of `(name, version, variant_index)` triples on
/// success, or `None` if the solve failed (including a construction error —
/// rez would error, but the benchmark records no error cases, so we treat
/// it as a failed solve).
fn solve(
    request: &[String],
    repo: Rc<PackageRepo>,
) -> Option<Vec<(String, String, Option<usize>)>> {
    let reqs: Vec<Requirement> = request.iter().map(|s| Requirement::parse(s)).collect();
    let mut solver = Solver::new(reqs, repo).ok()?;
    solver.solve();
    match solver.status() {
        SolverStatus::Solved => {
            let mut set: Vec<(String, String, Option<usize>)> = solver
                .resolved_packages()
                .unwrap()
                .iter()
                .map(|v| (v.name().to_string(), v.version().to_string(), v.index()))
                .collect();
            set.sort();
            set.dedup();
            Some(set)
        }
        SolverStatus::Failed => None,
        other => panic!("solver finished in unexpected status {other:?}"),
    }
}

#[test]
#[ignore = "full release run takes minutes; run via the benchmark CI job or \
            `cargo test --release -p rer-resolver --test test_rez_benchmark -- --ignored`"]
fn test_rez_benchmark_correctness() {
    let Some(repo) =
        load_json::<RepoMap>("benchmark_packages.json").map(|m| Rc::new(PackageRepo::from_map(m)))
    else {
        eprintln!(
            "benchmark fixtures missing — skipping. Generate them with:\n  \
             git submodule update --init\n  \
             python scripts/prepare_benchmark_data.py"
        );
        return;
    };
    let cases: Vec<BenchmarkCase> =
        load_json("benchmark_expected.json").expect("benchmark_expected.json is missing");

    println!(
        "loaded {} package families, {} benchmark requests",
        repo.family_count(),
        cases.len()
    );

    let mut exact = 0usize;
    let mut both_failed = 0usize;
    let mut divergent: Vec<usize> = Vec::new();
    let mut divergent_details: Vec<String> = Vec::new();
    let mut status_mismatch: Vec<String> = Vec::new();
    let mut panicked: Vec<usize> = Vec::new();

    // Catch panics so one bad request does not abort the whole suite. Silence
    // the default hook so the run is not buried in backtraces.
    let prev_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(|_| {}));

    let (range_start, range_end) = bench_range(cases.len());
    for (i, case) in cases.iter().enumerate().take(range_end).skip(range_start) {
        if (i - range_start) % 25 == 0 {
            eprintln!("  ... case {i}/{range_end}");
        }
        let rez_solved = case.status == "success";
        let outcome = catch_unwind(AssertUnwindSafe(|| solve(&case.request, Rc::clone(&repo))));

        let rer_result = match outcome {
            Ok(result) => result,
            Err(_) => {
                panicked.push(i);
                continue;
            }
        };

        match rer_result {
            Some(rer_set) => {
                if !rez_solved {
                    status_mismatch.push(format!(
                        "case {i}: rez `{}` but rer solved — {:?}",
                        case.status, case.request
                    ));
                    continue;
                }
                let rez_set = case
                    .resolved_packages
                    .as_deref()
                    .map(normalize_rez)
                    .unwrap_or_default();
                if rer_set == rez_set {
                    exact += 1;
                } else {
                    // Build a compact diff: which (name, version, variant)
                    // entries are only in one side. Helps narrow down whether
                    // the divergence is a missing package, a wrong version,
                    // or just a different variant index.
                    let rer_only: Vec<_> =
                        rer_set.iter().filter(|t| !rez_set.contains(t)).collect();
                    let rez_only: Vec<_> =
                        rez_set.iter().filter(|t| !rer_set.contains(t)).collect();
                    divergent.push(i);
                    divergent_details.push(format!(
                        "case {i}: request={:?}\n  rer-only: {:?}\n  rez-only: {:?}",
                        case.request, rer_only, rez_only
                    ));
                }
            }
            None => {
                if rez_solved {
                    status_mismatch.push(format!(
                        "case {i}: rez `success` but rer failed — {:?}",
                        case.request
                    ));
                } else {
                    both_failed += 1;
                }
            }
        }
    }

    std::panic::set_hook(prev_hook);

    println!(
        "range [{range_start}, {range_end})  —  \
         exact: {exact}  divergent: {}  both-failed: {both_failed}  \
         status-mismatch: {}  panicked: {}",
        divergent.len(),
        status_mismatch.len(),
        panicked.len(),
    );
    if !divergent.is_empty() {
        println!("divergent cases (solved, but a different set than rez): {divergent:?}");
        for line in &divergent_details {
            println!("{line}");
        }
    }
    if !panicked.is_empty() {
        println!("cases that panicked the solver: {panicked:?}");
    }

    assert!(
        status_mismatch.is_empty(),
        "{} resolve(s) diverged from rez in status:\n{}",
        status_mismatch.len(),
        status_mismatch.join("\n"),
    );
    assert!(
        panicked.is_empty(),
        "{} resolve(s) panicked the solver (indices: {panicked:?})",
        panicked.len(),
    );
    assert!(
        divergent.is_empty(),
        "{} resolve(s) solved to a different package set than rez (indices: {divergent:?})",
        divergent.len(),
    );
}
